def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    danger_scores = []

    for oid, opp in opponents_status.items():
        if not opp.get('alive', False):
            continue
        alive.append(opp)
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))

        o_hp = float(opp.get('hp', 10))
        o_nowater = int(opp.get('no_water_days', 0))
        o_budget = float(opp.get('budget', 0))
        o_salary = float(opp.get('daily_salary', DAILY_SALARY))
        desperation = 0.0
        if o_hp <= 3:
            desperation += 1.2
        elif o_hp <= 5:
            desperation += 0.6
        desperation += 0.45 * o_nowater
        if o_budget > o_salary * 8:
            desperation += 0.5
        elif o_budget > o_salary * 4:
            desperation += 0.25
        if bid is not None:
            if float(bid) >= o_salary * 1.2:
                desperation += 0.7
            elif float(bid) >= o_salary * 0.9:
                desperation += 0.35
        danger_scores.append(desperation)

    if not alive:
        base = DAILY_SALARY * 0.22
        if hp <= 3 or no_water >= 1:
            base = DAILY_SALARY * 0.55
        return float(max(0.0, min(budget, base)))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    opp_pressure = max(danger_scores) if danger_scores else 0.0

    urgent = hp <= 3 or no_water >= 2
    semi_urgent = hp <= 5 or no_water >= 1

    target = DAILY_SALARY * 0.42 + scarcity * DAILY_SALARY * 0.28

    if highest_prev > 0:
        target = max(target, highest_prev + 2.1)
        if highest_prev >= 120:
            if urgent:
                target = max(target, highest_prev + 3.0)
            else:
                target = min(target, DAILY_SALARY * 0.48)
        elif highest_prev >= 85:
            if semi_urgent:
                target = max(target, highest_prev + 1.6)
            else:
                target = min(target, avg_prev * 0.82)

    if opp_pressure >= 1.8:
        target += 8.0
    elif opp_pressure >= 1.0:
        target += 4.0

    if urgent:
        target = max(target, DAILY_SALARY * 0.95 + scarcity * 10.0)
    elif semi_urgent:
        target = max(target, DAILY_SALARY * 0.72 + scarcity * 8.0)
    else:
        if scarcity < 0.35 and highest_prev >= 85:
            target = min(target, DAILY_SALARY * 0.38)

    remaining_days = max(1, 10 - day)
    reserve_floor = remaining_days * DAILY_SALARY * 0.18
    spend_cap = budget
    if budget > reserve_floor:
        spend_cap = max(0.0, budget - reserve_floor * 0.15)

    if day >= 8:
        spend_cap = budget
        if semi_urgent:
            target += 6.0

    bid = min(spend_cap, target)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents alive, bid conservatively
    if not alive_opps:
        bid = min(budget, DAILY_SALARY * 0.35)
        return max(0.0, bid)

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for _opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = sorted(prev_bids, reverse=True)[1] if len(prev_bids) >= 2 else 0.0

    # Pressure estimate: if someone previously bid very high, we must not be too low.
    # Cindy reached ~128 and Eric ~84.6; use those as thresholds.
    pressure = 0.0
    if highest_prev >= 0.95 * DAILY_SALARY:
        pressure = 1.0
    elif highest_prev >= 0.75 * DAILY_SALARY:
        pressure = 0.7
    elif highest_prev >= 0.55 * DAILY_SALARY:
        pressure = 0.45
    else:
        pressure = 0.25

    # Supply scarcity factor: lower supply => higher bid.
    # supply in [15,25]; map to [1.0..0.6]
    scarcity = 1.0 - (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY + 1e-9)
    scarcity = max(0.0, min(1.0, scarcity))

    # Survival urgency: if we've already missed water days, increase bid.
    urgency = 0.0
    if no_water_days >= 2:
        urgency = 1.0
    elif no_water_days == 1:
        urgency = 0.6
    else:
        urgency = 0.2

    # Base target bid: aim around a fraction of daily salary, adjusted by pressure/scarcity/urgency.
    # Avoid overpaying above the likely competition ceiling (near highest_prev) but be high enough to beat mid bids.
    target = DAILY_SALARY * (0.45 + 0.25 * pressure + 0.15 * scarcity + 0.25 * urgency)

    # If yesterday's highest bid was strong, consider matching just below it.
    if highest_prev > 0:
        # Bid slightly above second-highest to beat the runner-up, but cap near highest_prev.
        if second_prev > 0:
            target = max(target, second_prev + 2.0)
        # If target is too low versus highest_prev, lift it modestly.
        if target < highest_prev * 0.88:
            target = highest_prev * (0.88 + 0.04 * scarcity)

    # If our hp is low, we must secure water.
    if hp <= 2.0:
        target = max(target, DAILY_SALARY * 0.9)
    elif hp <= 4.0:
        target = max(target, DAILY_SALARY * 0.7)

    # Ensure we don't exceed budget and keep non-negative.
    bid = min(budget, target)

    # Additional safety: if budget is small, still bid something meaningful but not suicidal.
    if budget <= DAILY_SALARY * 0.35:
        bid = min(budget, DAILY_SALARY * 0.6)

    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    base_bid = DAILY_SALARY * 0.5

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    current_bid = base_bid
    if my_status['hp'] <= 2:
        current_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 5:
        current_bid = DAILY_SALARY * 0.8

    if day_context['supply'] <= WATER_REQ * 1.5:
        current_bid = max(current_bid, DAILY_SALARY * 0.7)
        if day_context['supply'] < WATER_REQ + 5:
             current_bid = max(current_bid, DAILY_SALARY * 0.85)

    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            current_bid = max(current_bid, highest_prev_bid + 5.0)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            current_bid = max(current_bid, highest_prev_bid + 2.0)

    final_bid = min(my_status['budget'], current_bid)

    if day_context['day'] == EPISODE_DAYS and my_status['hp'] < 10:
        final_bid = my_status['budget']

    if final_bid <= 0.0 and my_status['budget'] > 0:
        final_bid = min(my_status['budget'], 1.0)

    return max(0.0, final_bid)

